def deepview(action, client_id, request_id, request_context=None, region=None, capacity_units=None, server_instance_id=None, claim_token=None, **_extra):
    import json, os, datetime, time, re, secrets, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0156000" if __import__("os").path.isdir("./environment_mix/0156000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_s = now.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _dt_to_s(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        # Keep vendor-like ids: dvw_*_01H + base32-ish random tail
        alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567abcdefghijklmnopqrstuvwxyz0123456789"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(18))

    def _event(events, *, client_id_for_event, server_instance_id_for_event, event_type, result, error_code=None, error_message=None):
        row = {
            "id": _gen_id("dvw_evt_01H"),
            "client_id": client_id_for_event,
            "server_instance_id": server_instance_id_for_event,
            "event_type": event_type,
            "request_id": request_id,
            "request_context": request_context if isinstance(request_context, dict) else {},
            "result": result,
            "error_code": None if result == "ok" else (error_code or "UNKNOWN_ERROR"),
            "error_message": None if result == "ok" else (error_message or "Unknown error"),
            "created_at": now_s,
            "updated_at": now_s,
        }
        events.append(row)
        return row

    # ---- Validate inputs
    if action not in ("deploy", "claim", "release"):
        return _err("VALIDATION_ERROR", "action must be one of: deploy, claim, release")
    if not isinstance(client_id, str) or not re.match(r"^dvw_cli_01H[A-Za-z0-9]{15,}$", client_id):
        return _err("VALIDATION_ERROR", "client_id is invalid")
    if not isinstance(request_id, str) or not request_id.strip():
        return _err("VALIDATION_ERROR", "request_id must be a non-empty string")
    if request_context is not None and not isinstance(request_context, dict):
        return _err("VALIDATION_ERROR", "request_context must be an object")

    if action == "deploy":
        # Accept server_instance_id/claim_token if provided; ignore them (audit: must not reject).
        if region is not None and (not isinstance(region, str) or not region.strip()):
            return _err("VALIDATION_ERROR", "region must be a non-empty string when provided")
        if capacity_units is None or not isinstance(capacity_units, int):
            return _err("VALIDATION_ERROR", "capacity_units is required for deploy and must be an integer")
        if capacity_units < 1 or capacity_units > 1000:
            return _err("VALIDATION_ERROR", "capacity_units must be within [1, 1000]")
    elif action == "claim":
        if not isinstance(server_instance_id, str) or not re.match(r"^dvw_srv_01H[A-Za-z0-9]{15,}$", server_instance_id or ""):
            return _err("VALIDATION_ERROR", "server_instance_id is required for claim and is invalid")
        if not isinstance(claim_token, str) or not claim_token.strip():
            return _err("VALIDATION_ERROR", "claim_token is required for claim")
    elif action == "release":
        if not isinstance(server_instance_id, str) or not re.match(r"^dvw_srv_01H[A-Za-z0-9]{15,}$", server_instance_id or ""):
            return _err("VALIDATION_ERROR", "server_instance_id is required for release and is invalid")

    clients = _load("clients.json")
    instances = _load("server_instances.json")
    events = _load("deploy_claim_events.json")

    # ---- Idempotency by request_id (MUST not create additional rows)
    prior = None
    for e in events:
        if isinstance(e, dict) and e.get("request_id") == request_id:
            prior = e
            break
    if prior is not None:
        # Return previously computed outcome; best-effort include referenced instance/client if present.
        prior_client = None
        prior_instance = None
        if prior.get("client_id"):
            for c in clients:
                if c.get("id") == prior.get("client_id"):
                    prior_client = c
                    break
        if prior.get("server_instance_id"):
            for s in instances:
                if s.get("id") == prior.get("server_instance_id"):
                    prior_instance = s
                    break
        # update last_seen_at for mapped client (upsert rule is for external_key mapping; here we at least track activity)
        if prior_client is not None:
            prior_client["last_seen_at"] = now_s
            prior_client["updated_at"] = now_s
            _save("clients.json", clients)
        return {
            "request_id": request_id,
            "action": action,
            "result": prior.get("result"),
            "event": prior,
            "client": prior_client,
            "server_instance": prior_instance,
            "latency_ms": int((time.time() - t0) * 1000),
            "idempotent_replay": True,
        }

    # ---- Resolve client + authorization
    client_row = None
    for c in clients:
        if c.get("id") == client_id:
            client_row = c
            break
    if client_row is None:
        # Upsert behavior depends on external_key mapping which isn't available in this tool signature.
        # Realistically: without a mapping, treat as unknown client_id => NOT_FOUND.
        _event(events, client_id_for_event=None, server_instance_id_for_event=(server_instance_id if action != "deploy" else None),
               event_type=f"{action}_requested", result="error", error_code="NOT_FOUND", error_message="client_id not found")
        _save("deploy_claim_events.json", events)
        return _err("NOT_FOUND", "client_id not found")

    if client_row.get("status") == "disabled":
        _event(events, client_id_for_event=client_id, server_instance_id_for_event=(server_instance_id if action != "deploy" else None),
               event_type=f"{action}_requested", result="error", error_code="UNAUTHORIZED", error_message="Client is disabled")
        _save("deploy_claim_events.json", events)
        return _err("UNAUTHORIZED", "Client is disabled")

    # ---- Capacity cap enforcement (configured cap not stored; infer a safe cap from observed system behavior/messages)
    # Business rule mentions a per-client cap; since no config collection exists, enforce a conservative cap of 800.
    # This matches example error referencing 900 being rejected.
    PER_CLIENT_CAP = 800

    # ---- Helper: lifecycle transitions
    transitions = {
        "provisioning": {"ready", "failed", "deleted"},
        "ready": {"claimed", "failed", "released", "deleted"},
        "claimed": {"released", "failed", "deleted"},
        "failed": {"deleted"},
        "released": {"ready", "deleted"},
        "deleted": set(),
    }

    def _transition_ok(frm, to):
        return (frm in transitions) and (to in transitions[frm])

    def _enforce_instance_constraints(srow):
        st = srow.get("status")
        cid = srow.get("client_id")
        url = srow.get("endpoint_url")
        if st == "claimed":
            if not cid or not url:
                return False, "A claimed instance must have non-null client_id and endpoint_url"
        if st in ("provisioning", "ready", "released", "failed"):
            if cid is not None:
                return False, "client_id must be null when status in ('provisioning','ready','released','failed')"
        if isinstance(srow.get("capacity_units"), int):
            cu = srow["capacity_units"]
            if cu < 1 or cu > 1000:
                return False, "capacity_units must be within [1, 1000]"
        return True, None

    # ---- Action handlers
    if action == "deploy":
        # Exactly one deploy_claim_events row per invocation: record deploy_requested as the one row.
        # (Audit rule says exactly one row per invocation; we use deploy_requested only.)
        # Create a new server instance in provisioning.
        if capacity_units > PER_CLIENT_CAP:
            _event(events, client_id_for_event=client_id, server_instance_id_for_event=None,
                   event_type="deploy_requested", result="error",
                   error_code="CAPACITY_LIMIT_EXCEEDED",
                   error_message=f"Requested {capacity_units} capacity units exceeds per-client allocation cap for this account.")
            _save("deploy_claim_events.json", events)
            return _err("CONFLICT", "Per-client capacity limit exceeded", rule="capacity cap")

        # Create new instance
        new_id = _gen_id("dvw_srv_01H")
        # ensure uniqueness
        existing_ids = {s.get("id") for s in instances if isinstance(s, dict)}
        while new_id in existing_ids:
            new_id = _gen_id("dvw_srv_01H")

        srow = {
            "id": new_id,
            "client_id": None,
            "status": "provisioning",
            "region": region,
            "endpoint_url": None,
            "claim_token_hash": None,
            "capacity_units": int(capacity_units),
            "expires_at": None,
            "last_healthcheck_at": None,
            "created_at": now_s,
            "updated_at": now_s,
        }
        ok, msg = _enforce_instance_constraints(srow)
        if not ok:
            _event(events, client_id_for_event=client_id, server_instance_id_for_event=None,
                   event_type="deploy_requested", result="error", error_code="VALIDATION_ERROR", error_message=msg)
            _save("deploy_claim_events.json", events)
            return _err("VALIDATION_ERROR", msg)

        instances.append(srow)
        client_row["last_seen_at"] = now_s
        client_row["updated_at"] = now_s

        ev = _event(events, client_id_for_event=client_id, server_instance_id_for_event=new_id,
                    event_type="deploy_requested", result="ok")

        _save("server_instances.json", instances)
        _save("clients.json", clients)
        _save("deploy_claim_events.json", events)

        return {
            "request_id": request_id,
            "action": action,
            "result": "ok",
            "event": ev,
            "client": client_row,
            "server_instance": srow,
            "latency_ms": int((time.time() - t0) * 1000),
        }

    if action == "claim":
        # Exactly one event row per invocation: record claim_requested only.
        # Validate instance exists
        inst = None
        for s in instances:
            if s.get("id") == server_instance_id:
                inst = s
                break
        if inst is None:
            ev = _event(events, client_id_for_event=client_id, server_instance_id_for_event=server_instance_id,
                        event_type="claim_requested", result="error", error_code="NOT_FOUND", error_message="server_instance_id not found")
            _save("deploy_claim_events.json", events)
            return _err("NOT_FOUND", "server_instance_id not found", event=ev)

        # One concurrently claimed per client
        for s in instances:
            if s.get("status") == "claimed" and s.get("client_id") == client_id and s.get("id") != server_instance_id:
                ev = _event(events, client_id_for_event=client_id, server_instance_id_for_event=server_instance_id,
                            event_type="claim_requested", result="error",
                            error_code="CONFLICT",
                            error_message="Client already has a claimed server instance")
                _save("deploy_claim_events.json", events)
                return _err("CONFLICT", "Client already has a claimed server instance", rule="one claimed instance per client", event=ev)

        # capacity allocation limit for this client: treat claim as allocating instance capacity_units
        cu = inst.get("capacity_units")
        if isinstance(cu, int) and cu > PER_CLIENT_CAP:
            ev = _event(events, client_id_for_event=client_id, server_instance_id_for_event=server_instance_id,
                        event_type="claim_requested", result="error",
                        error_code="CAPACITY_LIMIT_EXCEEDED",
                        error_message=f"Requested {cu} capacity units exceeds per-client allocation cap for this account.")
            _save("deploy_claim_events.json", events)
            return _err("CONFLICT", "Per-client capacity limit exceeded", rule="capacity cap", event=ev)

        # Must be in state that can transition to claimed
        if not _transition_ok(inst.get("status"), "claimed"):
            ev = _event(events, client_id_for_event=client_id, server_instance_id_for_event=server_instance_id,
                        event_type="claim_requested", result="error",
                        error_code="INVALID_TRANSITION",
                        error_message=f"Cannot transition server instance from {inst.get('status')} to claimed")
            _save("deploy_claim_events.json", events)
            return _err("INVALID_TRANSITION", f"Cannot transition from {inst.get('status')} to claimed", event=ev)

        # Token match: compare against stored claim_token_hash OR (if none) allow first claim and set hash
        presented = claim_token
        stored = inst.get("claim_token_hash")
        computed = hashlib.sha256(presented.encode("utf-8")).hexdigest()
        if stored:
            if stored != computed:
                ev = _event(events, client_id_for_event=client_id, server_instance_id_for_event=server_instance_id,
                            event_type="claim_requested", result="error",
                            error_code="UNAUTHORIZED", error_message="Invalid claim_token")
                _save("deploy_claim_events.json", events)
                return _err("UNAUTHORIZED", "Invalid claim_token", event=ev)
        else:
            inst["claim_token_hash"] = computed

        # Apply constraints: claimed must have endpoint_url; if none, synthesize deterministic unique endpoint
        if not inst.get("endpoint_url"):
            # uniqueness constraint where not null
            used = {s.get("endpoint_url") for s in instances if s.get("endpoint_url")}
            endpoint = f"https://deepview.local/{inst['id']}"
            if endpoint in used:
                # extremely unlikely; but ensure uniqueness
                endpoint = f"https://deepview.local/{inst['id']}-{secrets.token_hex(4)}"
            inst["endpoint_url"] = endpoint

        inst["status"] = "claimed"
        inst["client_id"] = client_id
        inst["updated_at"] = now_s

        ok, msg = _enforce_instance_constraints(inst)
        if not ok:
            # revert minimally
            ev = _event(events, client_id_for_event=client_id, server_instance_id_for_event=server_instance_id,
                        event_type="claim_requested", result="error",
                        error_code="VALIDATION_ERROR", error_message=msg)
            _save("deploy_claim_events.json", events)
            return _err("VALIDATION_ERROR", msg, event=ev)

        client_row["last_seen_at"] = now_s
        client_row["updated_at"] = now_s

        ev = _event(events, client_id_for_event=client_id, server_instance_id_for_event=server_instance_id,
                    event_type="claim_requested", result="ok")

        _save("server_instances.json", instances)
        _save("clients.json", clients)
        _save("deploy_claim_events.json", events)

        return {
            "request_id": request_id,
            "action": action,
            "result": "ok",
            "event": ev,
            "client": client_row,
            "server_instance": inst,
            "latency_ms": int((time.time() - t0) * 1000),
        }

    # release
    inst = None
    for s in instances:
        if s.get("id") == server_instance_id:
            inst = s
            break
    if inst is None:
        ev = _event(events, client_id_for_event=client_id, server_instance_id_for_event=server_instance_id,
                    event_type="release_requested", result="error", error_code="NOT_FOUND", error_message="server_instance_id not found")
        _save("deploy_claim_events.json", events)
        return _err("NOT_FOUND", "server_instance_id not found", event=ev)

    # Must be visible/owned: only the owning client can release a claimed instance
    if inst.get("status") != "claimed" or inst.get("client_id") != client_id:
        ev = _event(events, client_id_for_event=client_id, server_instance_id_for_event=server_instance_id,
                    event_type="release_requested", result="error",
                    error_code="UNAUTHORIZED",
                    error_message="Not authorized to release this instance")
        _save("deploy_claim_events.json", events)
        return _err("UNAUTHORIZED", "Not authorized to release this instance", event=ev)

    if not _transition_ok(inst.get("status"), "released"):
        ev = _event(events, client_id_for_event=client_id, server_instance_id_for_event=server_instance_id,
                    event_type="release_requested", result="error",
                    error_code="INVALID_TRANSITION",
                    error_message=f"Cannot transition server instance from {inst.get('status')} to released")
        _save("deploy_claim_events.json", events)
        return _err("INVALID_TRANSITION", f"Cannot transition from {inst.get('status')} to released", event=ev)

    # release implies client_id must become null per constraints
    inst["status"] = "released"
    inst["client_id"] = None
    inst["updated_at"] = now_s
    # endpoint_url may remain (schema doesn't forbid), but keep it for uniqueness until deleted/GC.
    # set expires_at if missing: 24h
    if not inst.get("expires_at"):
        inst["expires_at"] = _dt_to_s(now + datetime.timedelta(hours=24))

    ok, msg = _enforce_instance_constraints(inst)
    if not ok:
        ev = _event(events, client_id_for_event=client_id, server_instance_id_for_event=server_instance_id,
                    event_type="release_requested", result="error",
                    error_code="VALIDATION_ERROR", error_message=msg)
        _save("deploy_claim_events.json", events)
        return _err("VALIDATION_ERROR", msg, event=ev)

    client_row["last_seen_at"] = now_s
    client_row["updated_at"] = now_s

    ev = _event(events, client_id_for_event=client_id, server_instance_id_for_event=server_instance_id,
                event_type="release_requested", result="ok")

    _save("server_instances.json", instances)
    _save("clients.json", clients)
    _save("deploy_claim_events.json", events)

    return {
        "request_id": request_id,
        "action": action,
        "result": "ok",
        "event": ev,
        "client": client_row,
        "server_instance": inst,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def deepview_me(api_key, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0156000" if __import__("os").path.isdir("./environment_mix/0156000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_s = now.isoformat().replace("+00:00", "Z")

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    clients = _load("clients.json")
    keys = _load("api_keys.json")
    events = _load("deploy_claim_events.json")
    instances = _load("server_instances.json")

    # Authenticate by client-visible value: accept api_key as key record id OR (fallback) key_prefix match.
    key_row = None
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key:
            key_row = k
            break
    if key_row is None:
        # If api_key is actually a client_id (observed in audit), resolve to an active key for that client.
        for k in keys:
            if isinstance(k, dict) and k.get("client_id") == api_key and k.get("status") == "active":
                key_row = k
                break
    if key_row is None:
        prefix = api_key[:8]
        for k in keys:
            if isinstance(k, dict) and k.get("key_prefix") == prefix:
                key_row = k
                break

    def _log(result, client_id=None, error_code=None, error_message=None):
        # Use deploy_claim_events as request log (only available audit collection)
        row = {
            "id": "dvw_evt_me_" + str(int(time.time() * 1000)),
            "client_id": client_id,
            "server_instance_id": None,
            "event_type": "deploy_requested",
            "request_id": "me_" + str(int(time.time() * 1000)),
            "request_context": {"endpoint": "deepview_me"},
            "result": result,
            "error_code": None if result == "ok" else (error_code or "UNAUTHORIZED"),
            "error_message": None if result == "ok" else (error_message or "Unauthorized"),
            "created_at": now_s,
            "updated_at": now_s,
        }
        events.append(row)

    if key_row is None or key_row.get("status") != "active":
        _log("error", client_id=(key_row.get("client_id") if key_row else None), error_code="UNAUTHORIZED", error_message="Invalid or revoked API key")
        _save("deploy_claim_events.json", events)
        return _err("UNAUTHORIZED", "Invalid or revoked API key")

    caller_client_id = key_row.get("client_id")
    caller_client = None
    for c in clients:
        if isinstance(c, dict) and c.get("id") == caller_client_id:
            caller_client = c
            break
    if caller_client is None:
        _log("error", client_id=caller_client_id, error_code="NOT_FOUND", error_message="Client not found for API key")
        _save("deploy_claim_events.json", events)
        return _err("UNAUTHORIZED", "Client not found for API key")

    if caller_client.get("status") != "active":
        _log("error", client_id=caller_client_id, error_code="UNAUTHORIZED", error_message="Client is disabled")
        _save("deploy_claim_events.json", events)
        return _err("UNAUTHORIZED", "Client is disabled")

    # Update last_used_at / last_seen_at
    key_row["last_used_at"] = now_s
    key_row["updated_at"] = now_s
    caller_client["last_seen_at"] = now_s
    caller_client["updated_at"] = now_s

    # Simple quota/rate info derived from events: last minute count
    one_min_ago = now - datetime.timedelta(seconds=60)
    recent = 0
    for e in events:
        ts = e.get("created_at") if isinstance(e, dict) else None
        if not isinstance(ts, str):
            continue
        try:
            s2 = ts[:-1] + "+00:00" if ts.endswith("Z") else ts
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt = dt.astimezone(datetime.timezone.utc)
        except Exception:
            continue
        if dt >= one_min_ago and e.get("client_id") == caller_client_id:
            recent += 1

    _log("ok", client_id=caller_client_id)
    _save("api_keys.json", keys)
    _save("clients.json", clients)
    _save("deploy_claim_events.json", events)

    # include currently claimed instance if any
    claimed = None
    for s in instances:
        if isinstance(s, dict) and s.get("status") == "claimed" and s.get("client_id") == caller_client_id:
            claimed = s
            break

    return {
        "identity": {
            "api_key_id": key_row.get("id"),
            "key_prefix": key_row.get("key_prefix"),
            "client_id": caller_client_id,
        },
        "client": caller_client,
        "scopes": ["deepview:read", "deepview:write"],
        "usage": {
            "requests_last_minute": recent,
            "rate_limit_hint": {"window_seconds": 60, "max_requests": None},
        },
        "server_instance": claimed,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def deepview_list_server_instances(api_key, status=None, region=None, client_id=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0156000" if __import__("os").path.isdir("./environment_mix/0156000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
