def deepview_update_server_instance(api_key, server_instance_id, status=None, expires_at=None, capacity_units=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0156000" if __import__("os").path.isdir("./environment_mix/0156000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _to_rfc3339(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _new_event_id():
        return "dvw_evt_" + datetime.datetime.now(datetime.timezone.utc).strftime("%y%m%d%H%M%S%f")

    def _new_request_id():
        return "req_upd_" + datetime.datetime.now(datetime.timezone.utc).strftime("%y%m%d%H%M%S%f")

    def _sanitize_context():
        return {"endpoint": "deepview_update_server_instance"}

    def _record_event(events_rows, client_id, instance_id, result, error_code=None, error_message=None, event_type="deploy_requested"):
        now = _now_utc()
        created = _to_rfc3339(now)
        evt = {
            "id": _new_event_id(),
            "client_id": client_id,
            "server_instance_id": instance_id,
            "event_type": event_type,
            "request_id": _new_request_id(),
            "request_context": _sanitize_context(),
            "result": result,
            "error_code": None if result == "ok" else (error_code or "UNAUTHORIZED"),
            "error_message": None if result == "ok" else (error_message or "Unauthorized"),
            "created_at": created,
            "updated_at": created,
        }
        events_rows.append(evt)
        return evt

    t0 = time.time()
    now = _now_utc()
    now_s = _to_rfc3339(now)

    # Validate inputs (relax id pattern to accept datastore ids like dvw_srv_01J...)
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(server_instance_id, str) or not server_instance_id.strip():
        return _err("VALIDATION_ERROR", "server_instance_id must be a non-empty string")
    if not re.match(r"^dvw_srv_01[A-Za-z0-9]{16,}$", server_instance_id):
        return _err("VALIDATION_ERROR", "server_instance_id is invalid")

    if status is not None and status not in ("failed", "deleted"):
        return _err("VALIDATION_ERROR", "status must be one of: failed, deleted")

    exp_dt = None
    if expires_at is not None:
        exp_dt = _parse_dt(expires_at)
        if exp_dt is None:
            return _err("VALIDATION_ERROR", "expires_at must be RFC3339 date-time")

    if capacity_units is not None:
        if not isinstance(capacity_units, int):
            return _err("VALIDATION_ERROR", "capacity_units must be an integer")
        if capacity_units < 1 or capacity_units > 1000:
            return _err("VALIDATION_ERROR", "capacity_units must be within [1, 1000]")

    clients = _load("clients.json")
    keys = _load("api_keys.json")
    events = _load("deploy_claim_events.json")
    instances = _load("server_instances.json")

    # Authenticate: api_keys.id OR api_keys.key_prefix OR clients.id (choose active key)
    key_row = None
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key:
            key_row = k
            break
    if key_row is None:
        for k in keys:
            if isinstance(k, dict) and k.get("key_prefix") == api_key and k.get("status") == "active":
                key_row = k
                break
    if key_row is None:
        for k in keys:
            if isinstance(k, dict) and k.get("client_id") == api_key and k.get("status") == "active":
                key_row = k
                break

    client_row = None
    if key_row is not None:
        cid = key_row.get("client_id")
        for c in clients:
            if isinstance(c, dict) and c.get("id") == cid:
                client_row = c
                break

    # Locate instance
    inst_idx = None
    inst = None
    for i, s in enumerate(instances):
        if isinstance(s, dict) and s.get("id") == server_instance_id:
            inst_idx = i
            inst = s
            break

    if key_row is None or client_row is None:
        _record_event(events, None, server_instance_id, "error", error_code="UNAUTHORIZED", error_message="Invalid or missing API key.")
        _save("deploy_claim_events.json", events)
        return _err("UNAUTHORIZED", "Invalid or missing API key")

    if client_row.get("status") != "active":
        _record_event(events, client_row.get("id"), server_instance_id, "error", error_code="UNAUTHORIZED", error_message="Client is disabled.")
        _save("deploy_claim_events.json", events)
        return _err("UNAUTHORIZED", "Client is disabled")

    # Must exist to mutate
    if inst is None:
        _record_event(events, client_row.get("id"), server_instance_id, "error", error_code="NOT_FOUND", error_message="Server instance not found.")
        _save("deploy_claim_events.json", events)
        # still persist last-used/seen
        client_row["last_seen_at"] = now_s
        client_row["updated_at"] = now_s
        key_row["last_used_at"] = now_s
        key_row["updated_at"] = now_s
        _save("clients.json", clients)
        _save("api_keys.json", keys)
        return _err("NOT_FOUND", "Server instance not found")

    # Authorization: if claimed, only owning client can update; if unclaimed, allow update only when client_id is null
    if inst.get("status") == "claimed":
        if inst.get("client_id") != client_row.get("id"):
            _record_event(events, client_row.get("id"), server_instance_id, "error", error_code="UNAUTHORIZED", error_message="Not authorized to update this server instance.")
            _save("deploy_claim_events.json", events)
            return _err("UNAUTHORIZED", "Not authorized to update this server instance")
    else:
        # Non-claimed instances must not be owned per business rule; if they are, datastore is inconsistent; refuse update as conflict
        if inst.get("client_id") is not None:
            _record_event(events, client_row.get("id"), server_instance_id, "error", error_code="CONFLICT", error_message="Instance violates invariant: client_id must be null unless status='claimed'.")
            _save("deploy_claim_events.json", events)
            return _err("CONFLICT", "Instance violates invariant: client_id must be null unless status='claimed'")

    # Apply allowed field updates
    changed = False

    # capacity_units update (mutable; enforce [1,1000] already checked)
    if capacity_units is not None and inst.get("capacity_units") != capacity_units:
        inst["capacity_units"] = capacity_units
        changed = True

    # expires_at update
    if expires_at is not None:
        exp_s = _to_rfc3339(exp_dt)
        if inst.get("expires_at") != exp_s:
            inst["expires_at"] = exp_s
            changed = True

    # status transitions (only to failed/deleted)
    if status is not None:
        cur = inst.get("status")
        allowed = {
            "provisioning": ["ready", "failed", "deleted"],
            "ready": ["claimed", "failed", "released", "deleted"],
            "claimed": ["released", "failed", "deleted"],
            "failed": ["deleted"],
            "released": ["ready", "deleted"],
            "deleted": [],
        }
        if cur not in allowed:
            _record_event(events, client_row.get("id"), server_instance_id, "error", error_code="INVALID_TRANSITION", error_message="Unknown current status.")
            _save("deploy_claim_events.json", events)
            return _err("INVALID_TRANSITION", "Unknown current status", current_status=cur, requested_status=status)

        if status not in allowed[cur]:
            _record_event(
                events,
                client_row.get("id"),
                server_instance_id,
                "error",
                error_code="INVALID_TRANSITION",
                error_message=f"Illegal transition {cur} -> {status}.",
                event_type="deploy_failed" if status == "failed" else "release_failed",
            )
            _save("deploy_claim_events.json", events)
            return _err("INVALID_TRANSITION", f"Illegal transition {cur} -> {status}", current_status=cur, requested_status=status)

        if cur != status:
            # enforce invariants when moving into failed/deleted
            if status in ("failed", "deleted"):
                # failed/deleted should not retain client_id unless it was claimed and then failed/deleted
                # schema says in failed: client_id must be null; enforce by clearing
                inst["client_id"] = None
                changed = True

            inst["status"] = status
            changed = True

    if not changed:
        # No success without effect for mutations
        _record_event(events, client_row.get("id"), server_instance_id, "error", error_code="CONFLICT", error_message="No changes requested.")
        _save("deploy_claim_events.json", events)
        return _err("CONFLICT", "No changes requested")

    # Update audit timestamps
    inst["updated_at"] = now_s
    instances[inst_idx] = inst

    # Update client/key usage stamps
    client_row["last_seen_at"] = now_s
    client_row["updated_at"] = now_s
    key_row["last_used_at"] = now_s
    key_row["updated_at"] = now_s

    # Record update event (reads/mutations must be observable)
    # Use a semantically close event_type available in schema; for failures handled above, we used deploy_failed/release_failed.
    _record_event(events, client_row.get("id"), server_instance_id, "ok", event_type="deploy_succeeded")

    _save("server_instances.json", instances)
    _save("clients.json", clients)
    _save("api_keys.json", keys)
    _save("deploy_claim_events.json", events)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "server_instance": inst,
        "meta": {
            "latency_ms": latency_ms,
            "timestamp": now_s,
        },
    }

