    if server_instance_id is not None and (not isinstance(server_instance_id, str) or not re.match(r"^dvw_srv_01H[A-Za-z0-9]{15,}$", server_instance_id)):
        return _err("VALIDATION_ERROR", "server_instance_id is invalid")
    if event_type is not None and event_type not in ("deploy_requested", "deploy_succeeded", "deploy_failed", "claim_requested", "claim_succeeded", "claim_failed", "release_requested", "release_succeeded", "release_failed"):
        return _err("VALIDATION_ERROR", "event_type is invalid")
    if result is not None and result not in ("ok", "error"):
        return _err("VALIDATION_ERROR", "result is invalid")
    if request_id is not None and (not isinstance(request_id, str) or not request_id.strip()):
        return _err("VALIDATION_ERROR", "request_id must be a non-empty string when provided")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be within [1, 200]")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    clients = _load("clients.json")
    keys = _load("api_keys.json")
    events = _load("deploy_claim_events.json")

    # Authenticate: accept key id, or client_id -> active key, or key_prefix
    key_row = None
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key:
            key_row = k
            break
    if key_row is None:
        for k in keys:
            if isinstance(k, dict) and k.get("client_id") == api_key and k.get("status") == "active":
                key_row = k
                break
    if key_row is None:
        prefix = api_key[:8]
        for k in keys:
            if isinstance(k, dict) and k.get("key_prefix") == prefix:
                key_row = k
                break

    def _log(result2, cid, error_code=None, error_message=None):
        events.append({
            "id": "dvw_evt_evtlist_" + str(int(time.time() * 1000)),
            "client_id": cid,
            "server_instance_id": server_instance_id if isinstance(server_instance_id, str) else None,
            "event_type": "deploy_requested",
            "request_id": "evtlist_" + str(int(time.time() * 1000)),
            "request_context": {"endpoint": "deepview_list_deploy_claim_events"},
            "result": result2,
            "error_code": None if result2 == "ok" else (error_code or "UNAUTHORIZED"),
            "error_message": None if result2 == "ok" else (error_message or "Unauthorized"),
            "created_at": now_s,
            "updated_at": now_s,
        })

    if key_row is None or key_row.get("status") != "active":
        _log("error", None, error_code="UNAUTHORIZED", error_message="Invalid or revoked API key")
        _save("deploy_claim_events.json", events)
        return _err("UNAUTHORIZED", "Invalid or revoked API key")

    caller_client_id = key_row.get("client_id")
    caller_client = None
    for c in clients:
        if isinstance(c, dict) and c.get("id") == caller_client_id:
            caller_client = c
            break
    if caller_client is None or caller_client.get("status") != "active":
        _log("error", caller_client_id, error_code="UNAUTHORIZED", error_message="Client not found or disabled")
        _save("deploy_claim_events.json", events)
        return _err("UNAUTHORIZED", "Client not found or disabled")

    if client_id is not None and client_id != caller_client_id:
        _log("error", caller_client_id, error_code="UNAUTHORIZED", error_message="Callers may only request their own client_id")
        _save("deploy_claim_events.json", events)
        return _err("UNAUTHORIZED", "Callers may only request their own client_id")

    # pagination cursor
    offset = 0
    if cursor:
        try:
            dec = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if dec.startswith("o:"):
                offset = int(dec.split(":", 1)[1])
        except Exception:
            offset = 0

    # filter scoped to caller client
    filtered = []
    for e in events:
        if not isinstance(e, dict):
            continue
        if e.get("client_id") != caller_client_id:
            continue
        if server_instance_id is not None and e.get("server_instance_id") != server_instance_id:
            continue
        if event_type is not None and e.get("event_type") != event_type:
            continue
        if result is not None and e.get("result") != result:
            continue
        if request_id is not None and e.get("request_id") != request_id:
            continue
        filtered.append(e)

    # order by created_at desc
    filtered.sort(key=lambda r: r.get("created_at") or "", reverse=True)

    total = len(filtered)
    page = filtered[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"o:{next_off}".encode("utf-8")).decode("utf-8").rstrip("=")

    # dynamics
    key_row["last_used_at"] = now_s
    key_row["updated_at"] = now_s
    caller_client["last_seen_at"] = now_s
    caller_client["updated_at"] = now_s
    _log("ok", caller_client_id)

    _save("api_keys.json", keys)
    _save("clients.json", clients)
    _save("deploy_claim_events.json", events)

    return {
        "data": page,
        "pagination": {"total": total, "limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more},
        "latency_ms": int((time.time() - t0) * 1000),
    }

def deepview_update_client(api_key, client_id, display_name=None, status=None, last_seen_at=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0156000" if __import__("os").path.isdir("./environment_mix/0156000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)
    now_s = now.isoformat().replace("+00:00", "Z")
    t0 = time.time()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(client_id, str) or not re.match(r"^dvw_cli_01H[A-Za-z0-9]{15,}$", client_id):
        return _err("VALIDATION_ERROR", "client_id is invalid")
    if display_name is not None:
        if not isinstance(display_name, str):
            return _err("VALIDATION_ERROR", "display_name must be a string")
        if not (1 <= len(display_name) <= 200) or not display_name.strip():
            return _err("VALIDATION_ERROR", "display_name must be 1..200 chars and non-empty")
    if status is not None and status != "disabled":
        return _err("VALIDATION_ERROR", "status may only be set to 'disabled'")
    if last_seen_at is not None and _parse_dt(last_seen_at) is None:
        return _err("VALIDATION_ERROR", "last_seen_at must be RFC3339 date-time")

    clients = _load("clients.json")
    keys = _load("api_keys.json")
    events = _load("deploy_claim_events.json")

    # Authenticate: accept key id, or client_id -> active key, or key_prefix
    key_row = None
    for k in keys:
        if isinstance(k, dict) and k.get("id") == api_key:
            key_row = k
            break
    if key_row is None:
        for k in keys:
            if isinstance(k, dict) and k.get("client_id") == api_key and k.get("status") == "active":
                key_row = k
                break
    if key_row is None:
        prefix = api_key[:8]
        for k in keys:
            if isinstance(k, dict) and k.get("key_prefix") == prefix:
                key_row = k
                break

    def _log(result, cid, error_code=None, error_message=None):
        events.append({
            "id": "dvw_evt_cliupd_" + str(int(time.time() * 1000)),
            "client_id": cid,
            "server_instance_id": None,
            "event_type": "deploy_requested",
            "request_id": "cliupd_" + str(int(time.time() * 1000)),
            "request_context": {"endpoint": "deepview_update_client"},
            "result": result,
            "error_code": None if result == "ok" else (error_code or "UNAUTHORIZED"),
            "error_message": None if result == "ok" else (error_message or "Unauthorized"),
            "created_at": now_s,
            "updated_at": now_s,
        })

    if key_row is None or key_row.get("status") != "active":
        _log("error", None, error_code="UNAUTHORIZED", error_message="Invalid or revoked API key")
        _save("deploy_claim_events.json", events)
        return _err("UNAUTHORIZED", "Invalid or revoked API key")

    caller_client_id = key_row.get("client_id")
    if client_id != caller_client_id:
        _log("error", caller_client_id, error_code="UNAUTHORIZED", error_message="Callers may only update their own client")
        _save("deploy_claim_events.json", events)
        return _err("UNAUTHORIZED", "Callers may only update their own client")

    client_row = None
    for c in clients:
        if isinstance(c, dict) and c.get("id") == client_id:
            client_row = c
            break
    if client_row is None:
        _log("error", caller_client_id, error_code="NOT_FOUND", error_message="client not found")
        _save("deploy_claim_events.json", events)
        return _err("NOT_FOUND", "client not found")

    if client_row.get("status") == "disabled":
        # cannot re-enable; updating display_name/last_seen allowed? tool says can transition active->disabled; refuse re-enable attempts.
        if status == "disabled":
            # idempotent: already disabled -> no mutation
            _log("ok", caller_client_id)
            _save("deploy_claim_events.json", events)
            return {"data": client_row, "latency_ms": int((time.time() - t0) * 1000), "idempotent_replay": True}
        _log("error", caller_client_id, error_code="INVALID_TRANSITION", error_message="Cannot modify a disabled client")
        _save("deploy_claim_events.json", events)
        return _err("INVALID_TRANSITION", "Cannot modify a disabled client")

    changed = False
    if display_name is not None and display_name != client_row.get("display_name"):
        if not display_name.strip():
            _log("error", caller_client_id, error_code="VALIDATION_ERROR", error_message="display_name <> ''")
            _save("deploy_claim_events.json", events)
            return _err("VALIDATION_ERROR", "display_name must be non-empty (rule: display_name <> '')")
        client_row["display_name"] = display_name
        changed = True

    if last_seen_at is not None:
        client_row["last_seen_at"] = _parse_dt(last_seen_at).isoformat().replace("+00:00", "Z")
        changed = True
    else:
        # always touch last_seen_at on successful authenticated update call
        client_row["last_seen_at"] = now_s
        changed = True

    if status == "disabled":
        # active -> disabled only
        if client_row.get("status") != "active":
            _log("error", caller_client_id, error_code="INVALID_TRANSITION", error_message="Only active→disabled is allowed")
            _save("deploy_claim_events.json", events)
            return _err("INVALID_TRANSITION", "Only active→disabled is allowed")
        client_row["status"] = "disabled"
        changed = True

    if not changed:
        _log("error", caller_client_id, error_code="NOT_FOUND", error_message="No fields to update")
        _save("deploy_claim_events.json", events)
        return _err("NOT_FOUND", "No fields to update")

    client_row["updated_at"] = now_s
    key_row["last_used_at"] = now_s
    key_row["updated_at"] = now_s

    _log("ok", caller_client_id)

    _save("clients.json", clients)
    _save("api_keys.json", keys)
    _save("deploy_claim_events.json", events)

    return {"data": client_row, "latency_ms": int((time.time() - t0) * 1000)}
